style.css:
@-moz-document domain("axiom.trade") {
/* Glow des boutons quick buy */
  [data-pulse-qb-face] button {
    background: rgba(255, 255, 255, 0.04) !important;
    border-radius: 8px !important;
    box-shadow:
      0 0 0 1px rgba(255, 255, 255, 0.45) inset,
      0 0 10px rgba(255, 255, 255, 0.25) inset,
      0 0 12px rgba(255, 255, 255, 0.2) !important;
    transition: box-shadow 0.2s ease, background 0.2s ease !important;
  }

  /* Glow plus fort au survol */
  [data-pulse-qb-face] button:hover {
    background: rgba(255, 255, 255, 0.08) !important;
    box-shadow:
      0 0 0 1px rgba(255, 255, 255, 0.8) inset,
      0 0 16px rgba(255, 255, 255, 0.4) inset,
      0 0 20px rgba(255, 255, 255, 0.4) !important;
  }

  /* Texte qui brille */
  [data-pulse-qb-face] button span {
    text-shadow: 0 0 6px rgba(255, 255, 255, 0.8);
  }

  /* Éclair qui brille */
  [data-pulse-qb-face] button i.ri-flashlight-fill {
    filter: drop-shadow(0 0 4px rgba(255, 255, 255, 0.9));
  }
}
